begin;
set local timezone='America/Bahia';
select no_plan();
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values('b11a3000-0000-4000-8000-000000000001','authenticated','authenticated','quality-files@example.test','',now(),'{}','{"name":"Quality Files QA","company_name":"Quality Files QA"}',now(),now());
select set_config('request.jwt.claims','{"sub":"b11a3000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('qf.company',private.current_company_id(),true);
select set_config('qf.manager',(select id from public.profiles where auth_user_id=auth.uid()),true);
insert into public.customers(id,company_id,name,document) values('jf-customer',private.current_company_id(),'Cliente arquivos QA','');
insert into public.orders(id,company_id,customer_id,customer_name,number,status,total_amount,paid_amount,payment_status,shipping_cost,deadline,notes) values('jf-order',private.current_company_id(),'jf-customer','Cliente arquivos QA','PED-11JF','orcamento',100,0,'pendente',0,now()+interval '2 days','QA');
create function pg_temp.qf(a text,patch jsonb default '{}') returns jsonb language sql as $$select public.quality_command(gen_random_uuid(),a,(select jsonb_build_object('id',id,'updated_at',updated_at) from public.quality_nonconformities where id=current_setting('qf.id')::uuid)||patch)$$;
grant execute on function pg_temp.qf(text,jsonb) to authenticated;
set local role authenticated;
select set_config('qf.id',public.quality_command(gen_random_uuid(),'create',jsonb_build_object('source_type','order','source_id','jf-order','source_updated_at',public.quality_origins('order','',0,'jf-order')#>>'{origin,version}','description','Caso sintético de arquivos e despesas','category','other','severity','low','affected_quantity',1,'assigned_profile_id',current_setting('qf.manager'),'cost_applicable',true))->>'id',true);
select set_config('qf.file',pg_temp.qf('file_reserve',jsonb_build_object('sha256',repeat('a',64),'bytes',100,'mime','image/png','caption','Foto sintética QA'))#>>'{file,id}',true);
select is(pg_temp.qf('file_reserve',jsonb_build_object('sha256',repeat('a',64),'bytes',100,'mime','image/png','caption','Foto sintética QA'))#>>'{file,id}',current_setting('qf.file'),'new nonce reuses pending identical content');
select throws_like($$select pg_temp.qf('file_reserve',jsonb_build_object('sha256',repeat('a',64),'bytes',101,'mime','image/png','caption','Foto sintética QA'))$$,'%incompatível%','same content reservation cannot change byte metadata');
select throws_like($$insert into storage.objects(bucket_id,name) values('quality-evidence','forged.png')$$,'%row-level security%','browser cannot upload arbitrary storage path');
reset role;
insert into storage.objects(bucket_id,name) select 'quality-evidence',path from public.quality_evidence where id=current_setting('qf.file')::uuid;
insert into public.role_permissions(company_id,path,roles) values(current_setting('qf.company'),'/quality',array[]::text[]) on conflict(company_id,path) do update set roles=excluded.roles;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select throws_like($$select public.quality_commit_upload(current_setting('qf.file')::uuid,'b11a3000-0000-4000-8000-000000000001',repeat('a',64),100)$$,'%Sem permissão atual%','worker revalidates role revoked during upload');
reset role;
delete from public.role_permissions where company_id=current_setting('qf.company') and path='/quality';
set local role service_role;
select lives_ok($$select public.quality_commit_upload(current_setting('qf.file')::uuid,'b11a3000-0000-4000-8000-000000000001',repeat('a',64),100)$$,'trusted worker commits normalized reserved object');
select lives_ok($$select public.quality_commit_upload(current_setting('qf.file')::uuid,'b11a3000-0000-4000-8000-000000000001',repeat('a',64),100)$$,'worker retry does not add another evidence event');
reset role;
select set_config('request.jwt.claims','{"sub":"b11a3000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$select public.quality_file_access(current_setting('qf.file')::uuid)$$,'ready evidence accessible through tenant-gated path');
select pg_temp.qf('file_remove',jsonb_build_object('evidence_id',current_setting('qf.file'),'reason','Remoção explícita da foto QA'));
select throws_like($$select public.quality_file_access(current_setting('qf.file')::uuid)$$,'%Sem permissão%','removed evidence cannot get a signed path');
select isnt(pg_temp.qf('file_reserve',jsonb_build_object('sha256',repeat('a',64),'bytes',100,'mime','image/png','caption','Foto sintética QA'))#>>'{file,id}',current_setting('qf.file'),'new upload never resurrects removed evidence');
select set_config('qf.pending',(select id::text from public.quality_evidence where nc_id=current_setting('qf.id')::uuid and state='pending'),true);
select pg_temp.qf('file_remove',jsonb_build_object('evidence_id',current_setting('qf.pending'),'reason','Encerrar reserva sintética QA'));
select pg_temp.qf('analyze','{"root_cause":"Origem sintética identificada","analysis":"Conferência de despesa sem impacto comercial"}');
select pg_temp.qf('action_define',jsonb_build_object('kind','adjustment','execution_mode','none','quantity',1,'assigned_profile_id',current_setting('qf.manager'),'notes','Ajuste documental QA sem ação física','requires_reinspection',false));
select set_config('qf.account',public.finance_command(gen_random_uuid(),'account_create','{"name":"Conta Quality QA","kind":"bank","amount":0}')#>>'{account,id}',true);
select set_config('qf.category',public.finance_command(gen_random_uuid(),'category_create','{"name":"Custos Quality QA","type":"despesa"}')->>'id',true);
select pg_temp.qf('cost_save','{"kind":"labor","description":"Mão de obra adicional QA","planned":10,"actual":10}');
select set_config('qf.cost',(select id::text from public.quality_costs where nc_id=current_setting('qf.id')::uuid),true);
select lives_ok($$select pg_temp.qf('cost_export',jsonb_build_object('cost_id',current_setting('qf.cost'),'account_id',current_setting('qf.account'),'category_id',current_setting('qf.category'),'date',current_date))$$,'explicit expense export uses canonical payable');
select lives_ok($$select pg_temp.qf('cost_export',jsonb_build_object('cost_id',current_setting('qf.cost'),'account_id',current_setting('qf.account'),'category_id',current_setting('qf.category'),'date',current_date))$$,'another nonce reuses existing payable');
select is((select count(*) from public.financial_transactions where company_id=current_setting('qf.company')),1::bigint,'one payable without duplicate');
select is((select count(*) from public.financial_transactions where company_id=current_setting('qf.company') and status='pago'),0::bigint,'unpaid expense does not move cash');
select throws_like($$select pg_temp.qf('cost_save',jsonb_build_object('cost_id',current_setting('qf.cost'),'kind','labor','description','Correção com obrigação ativa QA','planned',10,'actual',0,'reason','Correção sintética QA'))$$,'%Cancele a obrigação%','cannot rewrite expense linked to active payable');
select pg_temp.qf('cost_cancel',jsonb_build_object('cost_id',current_setting('qf.cost'),'reason','Cancelamento sintético QA'));
select throws_like($$select pg_temp.qf('cost_save',jsonb_build_object('cost_id',current_setting('qf.cost'),'kind','labor','description','Correção sem motivo suficiente','planned',10,'actual',0))$$,'%exige motivo%','cost correction requires audit reason');
select pg_temp.qf('cost_save',jsonb_build_object('cost_id',current_setting('qf.cost'),'kind','labor','description','Custo revertido QA','planned',0,'actual',0,'reason','Conciliação sintética sem gasto'));
select is((public.quality_source(current_date,current_date,current_setting('qf.id')::uuid)#>>array['summaries',current_setting('qf.id'),'actual'])::numeric,0::numeric,'explicit zero is known, not missing');
select is((select count(*) from public.quality_cost_history where nc_id=current_setting('qf.id')::uuid),5::bigint,'each cost command preserves audit snapshot including retry');
select is((select count(*) from public.financial_transactions where company_id=current_setting('qf.company') and cancelled_at is null),0::bigint,'fixture has no active obligation');
reset role;
select * from finish();rollback;
